12	// limitations under the License.
13	
14	`include "VX_define.vh"
15	
16	module VX_lsu_slice import VX_gpu_pkg::*; #(
17	    parameter `STRING INSTANCE_ID = "",
18	    parameter CORE_ID = 0
19	) (
20	    `SCOPE_IO_DECL
21	
22	    input wire              clk,
23	    input wire              reset,
24	
25	    // Inputs
26	    VX_execute_if.slave     execute_if,
27	
28	    // Outputs
29	    VX_result_if.master     result_if,
30	
31	    // The slice exposes the memory-client side as a VX_lsu_sched_if master;
32	    // the parent wires it into VX_lsu_scheduler.
33	    VX_lsu_sched_if.master  client_if
34	);
35	    localparam NUM_LANES    = `VX_CFG_NUM_LSU_LANES;
36	    localparam PID_BITS     = `CLOG2(`VX_CFG_NUM_THREADS / NUM_LANES);
37	    localparam LSUQ_SIZEW   = `LOG2UP(`VX_CFG_LSU_PENDING_SIZE);
38	    localparam REQ_ASHIFT   = `CLOG2(LSU_WORD_SIZE);
39	    localparam MEM_ASHIFT   = `CLOG2(`VX_CFG_MEM_BLOCK_SIZE);
40	    localparam MEM_ADDRW    = `VX_CFG_MEM_ADDR_WIDTH - MEM_ASHIFT;
41	    `UNUSED_PARAM (CORE_ID)
42	    `UNUSED_SPARAM (INSTANCE_ID)
43	
44	    // tag_width = header + op_type + align + pkt_addr + fence
45	    localparam TAG_WIDTH = $bits(lsu_header_t) + INST_LSU_BITS + (NUM_LANES * REQ_ASHIFT) + LSUQ_SIZEW + 1;
46	    `STATIC_ASSERT (TAG_WIDTH == LSU_CLIENT_TAG_WIDTH, ("LSU client tag width mismatch — pkg/slice out of sync"))
47	
48	    VX_result_if #(
49	        .data_t (lsu_result_t)
50	    ) result_rsp_if();
51	
52	    VX_result_if #(
53	        .data_t (lsu_result_t)
54	    ) result_no_rsp_if();
55	
56	    `UNUSED_VAR (execute_if.data.rs3_data)
57	
58	    // full address calculation — per-lane AGU (all address forms live in
59	    // VX_lsu_agu; this slice contains no address arithmetic).
60	
61	    wire req_is_fence, rsp_is_fence;
62	
63	    wire [NUM_LANES-1:0][`VX_CFG_XLEN-1:0] full_addr;
64	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_full_addr
65	        VX_lsu_agu lsu_agu (
66	            .base   (execute_if.data.rs1_data[i]),
67	            .stride (execute_if.data.rs2_data[i]),
68	            .offset (execute_if.data.op_args.lsu.offset),
69	            .pack   (execute_if.data.op_args.lsu.pack),
70	            .addr   (full_addr[i])
71	        );
72	    end
73	
74	    // address type + AMO classification — per-lane mem_bus_attr_t
75	    // carried through the scheduler's USER channel and out via the
76	    // lsu_mem_if's per-lane req_data.user field.
77	
78	    mem_bus_attr_t [NUM_LANES-1:0] mem_req_attr_struct;
79	    wire [NUM_LANES-1:0][MEM_ATTR_WIDTH-1:0] mem_req_attr;
80	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_mem_req_attr
81	        wire [MEM_ADDRW-1:0] block_addr = full_addr[i][MEM_ASHIFT +: MEM_ADDRW];
82	        // is I/O address
83	        wire [MEM_ADDRW-1:0] io_addr_start = MEM_ADDRW'(`VX_CFG_XLEN'(`VX_MEM_IO_BASE_ADDR) >> MEM_ASHIFT);
84	        wire [MEM_ADDRW-1:0] io_addr_end = MEM_ADDRW'(`VX_CFG_XLEN'(`VX_MEM_IO_END_ADDR) >> MEM_ASHIFT);
85	        assign mem_req_attr_struct[i].is_flush  = req_is_fence;
86	        assign mem_req_attr_struct[i].is_addr_io = (block_addr >= io_addr_start) && (block_addr < io_addr_end);
87	    `ifdef VX_CFG_LMEM_ENABLE
88	        // is local memory address
89	        wire [MEM_ADDRW-1:0] lmem_addr_start = MEM_ADDRW'(`VX_CFG_XLEN'(`VX_MEM_LMEM_BASE_ADDR) >> MEM_ASHIFT);
90	        wire [MEM_ADDRW-1:0] lmem_addr_end = MEM_ADDRW'((`VX_CFG_XLEN'(`VX_MEM_LMEM_BASE_ADDR) + `VX_CFG_XLEN'(1 << `VX_CFG_LMEM_LOG_SIZE)) >> MEM_ASHIFT);
91	        assign mem_req_attr_struct[i].is_addr_local = (block_addr >= lmem_addr_start) && (block_addr < lmem_addr_end);
92	    `else
93	        assign mem_req_attr_struct[i].is_addr_local = 1'b0;
94	    `endif
95	    `ifdef VX_CFG_EXT_A_ENABLE
96	        amo_req_t lane_amo;
97	        assign lane_amo.amo_valid    = execute_if.data.op_args.lsu.amo_valid;
98	        assign lane_amo.amo_op       = execute_if.data.op_args.lsu.amo_op;
99	        // amo_unsigned distinguishes signed/unsigned AMOMIN/MAX variants
100	        // (decoder collapses MINU/MAXU into MIN/MAX + this bit).
101	        assign lane_amo.amo_unsigned = execute_if.data.op_args.lsu.amo_unsigned;
102	        // make_hart_id(cid, wid, tid) — packed concatenation, low bits = tid.
103	        assign lane_amo.hart_id      = HART_ID_WIDTH'(
104	            (HART_ID_WIDTH'(CORE_ID) << (NW_BITS + NT_BITS))
105	          | (HART_ID_WIDTH'(execute_if.data.header.wid) << NT_BITS)
106	          |  HART_ID_WIDTH'(i)
107	        );
108	        assign mem_req_attr_struct[i].amo = lane_amo;
109	    `else
110	        // EXT_A disabled: tie the AMO sideband to zero so the bits don't
111	        // propagate as 'x under --x-assign unique (otherwise downstream
112	        // checks like VX_lmem_switch's amo-on-LMEM guard fire spuriously).
113	        assign mem_req_attr_struct[i].amo = '0;
114	    `endif
115	        assign mem_req_attr[i] = mem_req_attr_struct[i];
116	    end
117	
118	    // schedule memory request
119	
120	    wire                            mem_req_valid;
121	    wire [NUM_LANES-1:0]            mem_req_mask;
122	    wire                            mem_req_rw;
123	    wire [NUM_LANES-1:0][LSU_ADDR_WIDTH-1:0] mem_req_addr;
124	    wire [NUM_LANES-1:0][LSU_WORD_SIZE-1:0] mem_req_byteen;
125	    reg  [NUM_LANES-1:0][LSU_WORD_SIZE*8-1:0] mem_req_data;
126	    wire [TAG_WIDTH-1:0]            mem_req_tag;
127	    wire                            mem_req_ready;
128	
129	    wire                            mem_rsp_valid;
130	    wire [NUM_LANES-1:0]            mem_rsp_mask;
131	    wire [NUM_LANES-1:0][LSU_WORD_SIZE*8-1:0] mem_rsp_data;
132	    wire [TAG_WIDTH-1:0]            mem_rsp_tag;
133	    wire                            mem_rsp_sop;
134	    wire                            mem_rsp_eop;
135	    wire                            mem_rsp_ready;
136	
137	    wire mem_req_fire = mem_req_valid && mem_req_ready;
138	    wire mem_rsp_fire = mem_rsp_valid && mem_rsp_ready;
139	
140	    wire mem_rsp_sop_pkt, mem_rsp_eop_pkt;
141	    wire no_rsp_buf_valid, no_rsp_buf_ready;
142	
143	    wire [LSUQ_SIZEW-1:0] pkt_waddr, pkt_raddr;
144	
145	    // fence handling
146	
147	    reg fence_lock;
148	
149	    assign req_is_fence = inst_lsu_is_fence(execute_if.data.op_type);
150	
151	    always @(posedge clk) begin
152	        if (reset) begin
153	            fence_lock <= 0;
154	        end else begin
155	            if (mem_req_fire && req_is_fence && execute_if.data.header.eop) begin
156	                fence_lock <= 1;
157	            end
158	            if (mem_rsp_fire && rsp_is_fence && mem_rsp_eop_pkt) begin
159	                fence_lock <= 0;
160	            end
161	        end
162	    end
163	
164	    wire req_skip = req_is_fence && ~execute_if.data.header.eop;
165	    wire no_rsp_buf_enable = (mem_req_rw && ~execute_if.data.header.wb) || req_skip;
166	
167	    assign mem_req_valid = execute_if.valid
168	                        && ~req_skip
169	                        && ~(no_rsp_buf_enable && ~no_rsp_buf_ready)
170	                        && ~fence_lock;
171	
172	    assign no_rsp_buf_valid = execute_if.valid
173	                           && no_rsp_buf_enable
174	                           && (req_skip || mem_req_ready)
175	                           && ~fence_lock;
176	
177	    assign execute_if.ready = (mem_req_ready || req_skip)
178	                           && ~(no_rsp_buf_enable && ~no_rsp_buf_ready)
179	                           && ~fence_lock;
180	
181	    assign mem_req_mask = execute_if.data.header.tmask;
182	`ifdef VX_CFG_EXT_A_ENABLE
183	    // AMO MemReq.rw is unconditionally 0: a missing line under SC must
184	    // miss-and-return-failure, not write-and-succeed.
185	    assign mem_req_rw = execute_if.data.op_args.lsu.is_store
186	                     && ~execute_if.data.op_args.lsu.amo_valid;
187	`else
188	    assign mem_req_rw = execute_if.data.op_args.lsu.is_store;
189	`endif
190	
191	    // address formatting
192	
193	    wire [NUM_LANES-1:0][REQ_ASHIFT-1:0] req_align;
194	
195	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_mem_req_addr
196	        assign req_align[i] = full_addr[i][REQ_ASHIFT-1:0];
197	        assign mem_req_addr[i] = full_addr[i][`VX_CFG_MEM_ADDR_WIDTH-1:REQ_ASHIFT];
198	    end
199	
200	    // byte enable formatting
201	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_mem_req_byteen_w
202	        reg [LSU_WORD_SIZE-1:0] mem_req_byteen_w;
203	        always @(*) begin
204	            mem_req_byteen_w = '0;
205	            case (inst_lsu_wsize(execute_if.data.op_type))
206	                0: begin // 8-bit
207	                    mem_req_byteen_w[req_align[i]] = 1'b1;
208	                end
209	                1: begin // 16 bit
210	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:1], 1'b0}] = 1'b1;
211	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:1], 1'b1}] = 1'b1;
212	                end
213	            `ifdef VX_CFG_XLEN_64
214	                2: begin // 32 bit
215	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:2], 2'b00}] = 1'b1;
216	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:2], 2'b01}] = 1'b1;
217	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:2], 2'b10}] = 1'b1;
218	                    mem_req_byteen_w[{req_align[i][REQ_ASHIFT-1:2], 2'b11}] = 1'b1;
219	                end
220	            `endif
221	                // 3: 64 bit
222	                default : mem_req_byteen_w = {LSU_WORD_SIZE{1'b1}};
223	            endcase
224	        end
225	        assign mem_req_byteen[i] = mem_req_byteen_w;
226	    end
227	
228	    // memory misalignment not supported!
229	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_missalign
230	        wire lsu_req_fire = execute_if.valid && execute_if.ready;
231	        `RUNTIME_ASSERT((~lsu_req_fire || ~execute_if.data.header.tmask[i] || req_is_fence || (full_addr[i] % (1 << inst_lsu_wsize(execute_if.data.op_type))) == 0),
232	            ("%t: misaligned memory access, wid=%0d, PC=0x%0h, addr=0x%0h, wsize=%0d! (#%0d)",
233	                $time, execute_if.data.header.wid, to_fullPC(execute_if.data.header.PC), full_addr[i], inst_lsu_wsize(execute_if.data.op_type), execute_if.data.header.uuid))
234	    end
235	
236	    // store data formatting
237	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_mem_req_data
238	        always @(*) begin
239	            mem_req_data[i] = execute_if.data.rs2_data[i];
240	            case (req_align[i])
241	                1: mem_req_data[i][`VX_CFG_XLEN-1:8]  = execute_if.data.rs2_data[i][`VX_CFG_XLEN-9:0];
242	                2: mem_req_data[i][`VX_CFG_XLEN-1:16] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-17:0];
243	                3: mem_req_data[i][`VX_CFG_XLEN-1:24] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-25:0];
244	            `ifdef VX_CFG_XLEN_64
245	                4: mem_req_data[i][`VX_CFG_XLEN-1:32] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-33:0];
246	                5: mem_req_data[i][`VX_CFG_XLEN-1:40] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-41:0];
247	                6: mem_req_data[i][`VX_CFG_XLEN-1:48] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-49:0];
248	                7: mem_req_data[i][`VX_CFG_XLEN-1:56] = execute_if.data.rs2_data[i][`VX_CFG_XLEN-57:0];
249	            `endif
250	                default:;
251	            endcase
252	        end
253	    end
254	
255	    // multi-packet load responses could return out-of-order.
256	    // we should track and flag SOP and EOP responses.
257	
258	    if (PID_BITS != 0) begin : g_pid
259	        reg [`VX_CFG_LSU_PENDING_SIZE-1:0][PID_BITS:0] pkt_ctr;
260	        reg [`VX_CFG_LSU_PENDING_SIZE-1:0] pkt_sop, pkt_eop;
261	
262	        wire mem_req_rd_fire     = mem_req_fire && ~mem_req_rw;
263	        wire mem_req_rd_sop_fire = mem_req_rd_fire && execute_if.data.header.sop;
264	        wire mem_req_rd_eop_fire = mem_req_rd_fire && execute_if.data.header.eop;
265	        wire mem_rsp_eop_fire    = mem_rsp_fire && mem_rsp_eop;
266	        wire mem_rsp_eop_pkt_fire= mem_rsp_fire && mem_rsp_eop_pkt;
267	        wire full;
268	
269	        VX_allocator #(
270	            .SIZE (`VX_CFG_LSU_PENDING_SIZE)
271	        ) pkt_allocator (
272	            .clk        (clk),
273	            .reset      (reset),
274	            .acquire_en (mem_req_rd_eop_fire),
275	            .acquire_addr(pkt_waddr),
276	            .release_en (mem_rsp_eop_pkt_fire),
277	            .release_addr(pkt_raddr),
278	            `UNUSED_PIN (empty),
279	            .full       (full)
280	        );
281	
282	        wire rw_collision = mem_req_rd_fire && mem_rsp_eop_fire && (pkt_raddr == pkt_waddr);
283	
284	        always @(posedge clk) begin
285	            if (reset) begin
286	                pkt_ctr <= '0;
287	                pkt_sop <= '0;
288	                pkt_eop <= '0;
289	            end else begin
290	                if (mem_req_rd_sop_fire) begin
291	                    pkt_sop[pkt_waddr] <= 1;
292	                end
293	                if (mem_req_rd_eop_fire) begin
294	                    pkt_eop[pkt_waddr] <= 1;
295	                end
296	                if (mem_rsp_fire) begin
297	                    pkt_sop[pkt_raddr] <= 0;
298	                end
299	                if (mem_rsp_eop_pkt_fire) begin
300	                    pkt_eop[pkt_raddr] <= 0;
301	                end
302	                if (~rw_collision) begin
303	                    if (mem_req_rd_fire) begin
304	                        pkt_ctr[pkt_waddr] <= pkt_ctr[pkt_waddr] + PID_BITS'(1);
305	                    end
306	                    if (mem_rsp_eop_fire) begin
307	                        pkt_ctr[pkt_raddr] <= pkt_ctr[pkt_raddr] - PID_BITS'(1);
308	                    end
309	                end
310	            end
311	        end
312	
313	        assign mem_rsp_sop_pkt = pkt_sop[pkt_raddr];
314	        assign mem_rsp_eop_pkt = mem_rsp_eop && pkt_eop[pkt_raddr] && (pkt_ctr[pkt_raddr] == 1);
315	        `RUNTIME_ASSERT(~(mem_req_rd_fire && full), ("allocator full!"))
316	        `RUNTIME_ASSERT(~(mem_req_rd_sop_fire && pkt_ctr[pkt_waddr] != 0), ("oops! broken sop request!"))
317	        `UNUSED_VAR (mem_rsp_sop)
318	    end else begin : g_no_pid
319	        assign pkt_waddr = 0;
320	        assign mem_rsp_sop_pkt = mem_rsp_sop;
321	        assign mem_rsp_eop_pkt = mem_rsp_eop;
322	        `UNUSED_VAR (pkt_raddr)
323	    end
324	
325	    // pack memory request tag
326	    assign mem_req_tag = {
327	        execute_if.data.header,
328	        execute_if.data.op_type,
329	        req_align,
330	        pkt_waddr,
331	        req_is_fence
332	    };
333	
334	    // Pack per-lane mem_req signals into the client_if request payload;
335	    // unpack the response payload into per-lane mem_rsp signals.
336	    assign client_if.req_valid       = mem_req_valid;
337	    assign client_if.req_data.rw     = mem_req_rw;
338	    assign client_if.req_data.mask   = mem_req_mask;
339	    assign client_if.req_data.byteen = mem_req_byteen;
340	    assign client_if.req_data.addr   = mem_req_addr;
341	    assign client_if.req_data.attr   = mem_req_attr;
342	    assign client_if.req_data.data   = mem_req_data;
343	    assign client_if.req_data.tag    = mem_req_tag;
344	    assign mem_req_ready             = client_if.req_ready;
345	
346	    assign mem_rsp_valid             = client_if.rsp_valid;
347	    assign mem_rsp_mask              = client_if.rsp_data.mask;
348	    assign mem_rsp_data              = client_if.rsp_data.data;
349	    assign mem_rsp_tag               = client_if.rsp_data.tag;
350	    assign mem_rsp_sop               = client_if.rsp_data.sop;
351	    assign mem_rsp_eop               = client_if.rsp_data.eop;
352	    assign client_if.rsp_ready       = mem_rsp_ready;
353	
354	    lsu_header_t rsp_hdr;
355	    wire [INST_LSU_BITS-1:0] rsp_op_type;
356	    wire [NUM_LANES-1:0][REQ_ASHIFT-1:0] rsp_align;
357	    `UNUSED_VAR (rsp_op_type)
358	
359	    // unpack memory response tag
360	    assign {
361	        rsp_hdr,
362	        rsp_op_type,
363	        rsp_align,
364	        pkt_raddr,
365	        rsp_is_fence
366	    } = mem_rsp_tag;
367	
368	    // load response formatting
369	
370	    reg [NUM_LANES-1:0][`VX_CFG_XLEN-1:0] rsp_data;
371	
372	`ifdef VX_CFG_XLEN_64
373	`ifdef VX_CFG_EXT_F_ENABLE
374	    // apply nan-boxing to flw outputs
375	    wire rsp_is_float = (get_reg_type(rsp_hdr.rd) == REG_TYPE_F);
376	`else
377	    wire rsp_is_float = 0;
378	`endif
379	`endif
380	
381	    for (genvar i = 0; i < NUM_LANES; i++) begin : g_rsp_data
382	    `ifdef VX_CFG_XLEN_64
383	        wire [63:0] rsp_data64 = mem_rsp_data[i];
384	        wire [31:0] rsp_data32 = (rsp_align[i][2] ? mem_rsp_data[i][63:32] : mem_rsp_data[i][31:0]);
385	    `else
386	        wire [31:0] rsp_data32 = mem_rsp_data[i];
387	    `endif
388	        wire [15:0] rsp_data16 = rsp_align[i][1] ? rsp_data32[31:16] : rsp_data32[15:0];
389	        wire [7:0]  rsp_data8  = rsp_align[i][0] ? rsp_data16[15:8] : rsp_data16[7:0];
390	
391	        always @(*) begin
392	            case (inst_lsu_fmt(rsp_op_type))
393	            LSU_FMT_B:  rsp_data[i] = `VX_CFG_XLEN'(signed'(rsp_data8));
394	            LSU_FMT_H:  rsp_data[i] = `VX_CFG_XLEN'(signed'(rsp_data16));
395	            LSU_FMT_BU: rsp_data[i] = `VX_CFG_XLEN'(unsigned'(rsp_data8));
396	            LSU_FMT_HU: rsp_data[i] = `VX_CFG_XLEN'(unsigned'(rsp_data16));
397	        `ifdef VX_CFG_XLEN_64
398	            LSU_FMT_W:  rsp_data[i] = rsp_is_float ? (`VX_CFG_XLEN'(rsp_data32) | 64'hffffffff00000000) : `VX_CFG_XLEN'(signed'(rsp_data32));
399	            LSU_FMT_WU: rsp_data[i] = `VX_CFG_XLEN'(unsigned'(rsp_data32));
400	            LSU_FMT_D:  rsp_data[i] = `VX_CFG_XLEN'(signed'(rsp_data64));
401	        `else
402	            LSU_FMT_W:  rsp_data[i] = `VX_CFG_XLEN'(signed'(rsp_data32));
403	        `endif
404	            default: rsp_data[i] = 'x;
405	            endcase
406	        end
407	    end
408	
409	    // result
410	
411	    lsu_header_t rsp_hdr2;
412	    always @(*) begin
413	        rsp_hdr2 = rsp_hdr;
414	        rsp_hdr2.tmask = mem_rsp_mask;
415	        rsp_hdr2.sop = mem_rsp_sop_pkt;
416	        rsp_hdr2.eop = mem_rsp_eop_pkt;
417	    end
418	
419	    VX_elastic_buffer #(
420	        .DATAW ($bits(lsu_result_t)),
421	        .SIZE  (2)
422	    ) rsp_buf (
423	        .clk       (clk),
424	        .reset     (reset),
425	        .valid_in  (mem_rsp_valid),
426	        .ready_in  (mem_rsp_ready),
427	        .data_in   ({rsp_hdr2, rsp_data}),
428	        .data_out  (result_rsp_if.data),
429	        .valid_out (result_rsp_if.valid),
430	        .ready_out (result_rsp_if.ready)
431	    );
432	
433	    VX_elastic_buffer #(
434	        .DATAW ($bits(lsu_header_t)),
435	        .SIZE  (2)
436	    ) no_rsp_buf (
437	        .clk       (clk),
438	        .reset     (reset),
439	        .valid_in  (no_rsp_buf_valid),
440	        .ready_in  (no_rsp_buf_ready),
441	        .data_in   (execute_if.data.header),
442	        .data_out  (result_no_rsp_if.data.header),
443	        .valid_out (result_no_rsp_if.valid),
444	        .ready_out (result_no_rsp_if.ready)
445	    );
446	    assign result_no_rsp_if.data.data = result_rsp_if.data.data; // arbiter MUX optimization
447	
448	    VX_stream_arb #(
449	        .NUM_INPUTS (2),
450	        .DATAW      ($bits(lsu_result_t)),
451	        .ARBITER    ("P"), // prioritize result_rsp_if
452	        .OUT_BUF    (3)
453	    ) rsp_arb (
454	        .clk       (clk),
455	        .reset     (reset),
456	        .valid_in  ({result_no_rsp_if.valid, result_rsp_if.valid}),
457	        .ready_in  ({result_no_rsp_if.ready, result_rsp_if.ready}),
458	        .data_in   ({result_no_rsp_if.data, result_rsp_if.data}),
459	        .data_out  (result_if.data),
460	        .valid_out (result_if.valid),
461	        .ready_out (result_if.ready),
462	        `UNUSED_PIN (sel_out)
463	    );
464	
465	`ifdef DBG_TRACE_MEM
466	    always @(posedge clk) begin
467	        if (execute_if.valid && fence_lock) begin
468	            `TRACE(2, ("%t: *** %s fence wait\n", $time, INSTANCE_ID))
469	        end
470	        if (mem_req_fire) begin
471	            if (mem_req_rw) begin
472	                `TRACE(2, ("%t: %s Wr Req: wid=%0d, cta_id=%0d, PC=0x%0h, tmask=%b, addr=", $time, INSTANCE_ID, execute_if.data.header.wid, execute_if.data.header.cta_id, to_fullPC(execute_if.data.header.PC), mem_req_mask))
473	                `TRACE_ARRAY1D(2, "0x%h", full_addr, NUM_LANES)
474	                `TRACE(2, (", attr="))
475	                `TRACE_ARRAY1D(2, "%b", mem_req_attr, NUM_LANES)
476	                `TRACE(2, (", byteen=0x%0h, data=", mem_req_byteen))
477	                `TRACE_ARRAY1D(2, "0x%0h", mem_req_data, NUM_LANES)
478	                `TRACE(2, (", sop=%b, pid=%0d, eop=%b, tag=0x%0h (#%0d)\n", execute_if.data.header.pid, execute_if.data.header.sop, execute_if.data.header.eop, mem_req_tag, execute_if.data.header.uuid))
479	            end else begin
480	                `TRACE(2, ("%t: %s Rd Req: wid=%0d, cta_id=%0d, PC=0x%0h, tmask=%b, addr=", $time, INSTANCE_ID, execute_if.data.header.wid, execute_if.data.header.cta_id, to_fullPC(execute_if.data.header.PC), mem_req_mask))
481	                `TRACE_ARRAY1D(2, "0x%h", full_addr, NUM_LANES)
482	                `TRACE(2, (", attr="))
483	                `TRACE_ARRAY1D(2, "%b", mem_req_attr, NUM_LANES)
484	                `TRACE(2, (", byteen=0x%0h, rd=%0d, pid=%0d, sop=%b, eop=%b, tag=0x%0h (#%0d)\n", mem_req_byteen, execute_if.data.header.rd, execute_if.data.header.pid, execute_if.data.header.sop, execute_if.data.header.eop, mem_req_tag, execute_if.data.header.uuid))
485	            end
486	        end
487	        if (mem_rsp_fire) begin
488	            `TRACE(2, ("%t: %s Rsp: wid=%0d, cta_id=%0d, PC=0x%0h, tmask=%b, rd=%0d, pid=%0d, sop=%b, eop=%b, data=",
489	                $time, INSTANCE_ID, rsp_hdr.wid, rsp_hdr.cta_id, to_fullPC(rsp_hdr.PC), mem_rsp_mask, rsp_hdr.rd, rsp_hdr.pid, mem_rsp_sop_pkt, mem_rsp_eop_pkt))
490	            `TRACE_ARRAY1D(2, "0x%0h", mem_rsp_data, NUM_LANES)
491	            `TRACE(2, (", tag=0x%0h (#%0d)\n", mem_rsp_tag, rsp_hdr.uuid))
492	        end
493	    end
494	`endif
495	
496	
497	`ifdef SCOPE
498	`ifdef DBG_SCOPE_LSU
499	    `SCOPE_IO_SWITCH (1);
500	    wire reset_negedge;
501	    `NEG_EDGE (reset_negedge, reset);
502	    `SCOPE_TAP_EX (0, 3, 4, 2, (
503	            1 + NUM_LANES * (`VX_CFG_XLEN + LSU_WORD_SIZE + LSU_WORD_SIZE * 8) + UUID_WIDTH + NUM_LANES * LSU_WORD_SIZE * 8 + UUID_WIDTH
504	        ), {
505	            mem_req_valid,
506	            mem_req_ready,
507	            mem_rsp_valid,
508	            mem_rsp_ready
509	        }, {
510	            mem_req_fire,
511	            mem_rsp_fire
512	        }, {
513	            mem_req_rw,
514	            full_addr,
515	            mem_req_byteen,
516	            mem_req_data,
517	            execute_if.data.header.uuid,
518	            rsp_data,
519	            rsp_hdr.uuid
520	        },
521	        reset_negedge, 1'b0,	4096
522	    );
523	`else
524	    `SCOPE_IO_UNUSED(0)
525	`endif
526	`endif
527	
528	`ifdef CHIPSCOPE
529	`ifdef DBG_SCOPE_LSU
530	    ila_lsu ila_lsu_inst (
531	        .clk    (clk),
532	        .probe0 ({execute_if.valid, execute_if.data, execute_if.ready}),
533	        .probe1 ({client_if.req_valid, client_if.req_data, client_if.req_ready}),
534	        .probe2 ({client_if.rsp_valid, client_if.rsp_data, client_if.rsp_ready})
535	    );
536	`endif
537	`endif
538	
539	endmodule
540

